// Golden-vector tests: C++ LDA zone code vs the Python reference (test/data/zones_golden.txt,
// generated by tools/make_golden.py).
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unity.h>

#include <vector>

#include "zonemodel.h"

using namespace oralb;

struct Feat {
  double x[FEATURE_COUNT];
  int zone;
};

struct Golden {
  struct S { double t; int a[3], g[3]; };
  std::vector<S> samples, nogyro;           // S / SN lines
  std::vector<Feat> replay, replay_nogyro;  // F / FN lines
  std::vector<Feat> full;                   // G lines
  int trk_windows = 0, trk_current = -1;
  double cov[ZONE_COUNT];
};

static bool parse_feat(const char* p, Feat& f) {
  char* e;
  for (int i = 0; i < FEATURE_COUNT; i++) {
    f.x[i] = strtod(p, &e);
    if (e == p) return false;
    p = e;
  }
  f.zone = (int)strtol(p, &e, 10);
  return e != p;
}

static Golden& golden() {
  static Golden g;
  static bool loaded = false;
  if (loaded) return g;
  FILE* fp = fopen(TEST_DATA_DIR "/zones_golden.txt", "r");
  TEST_ASSERT_NOT_NULL_MESSAGE(fp, "cannot open test/data/zones_golden.txt (run from the repository root)");
  static char line[1024];
  while (fgets(line, sizeof line, fp)) {
    if (line[0] == '#') continue;
    char tag[8];
    int off = 0;
    if (sscanf(line, "%7s%n", tag, &off) < 1) continue;
    const char* p = line + off;
    if (!strcmp(tag, "S")) {
      Golden::S s;
      sscanf(p, "%lf %d %d %d %d %d %d", &s.t, &s.a[0], &s.a[1], &s.a[2], &s.g[0], &s.g[1], &s.g[2]);
      g.samples.push_back(s);
    } else if (!strcmp(tag, "SN")) {
      Golden::S s = {};
      sscanf(p, "%lf %d %d %d", &s.t, &s.a[0], &s.a[1], &s.a[2]);
      g.nogyro.push_back(s);
    } else if (!strcmp(tag, "F") || !strcmp(tag, "FN") || !strcmp(tag, "G")) {
      Feat f;
      TEST_ASSERT_TRUE(parse_feat(p, f));
      (tag[0] == 'G' ? g.full : (tag[1] == 'N' ? g.replay_nogyro : g.replay)).push_back(f);
    } else if (!strcmp(tag, "TRK")) {
      char* e;
      g.trk_windows = (int)strtol(p, &e, 10);
      g.trk_current = (int)strtol(e, &e, 10);
      for (int z = 0; z < ZONE_COUNT; z++) g.cov[z] = strtod(e, &e);
    }
  }
  fclose(fp);
  loaded = true;
  return g;
}

static void test_embedded_model_metadata() {
  TEST_ASSERT_EQUAL_INT(16, ZONE_COUNT);
  TEST_ASSERT_EQUAL_INT(12, FEATURE_COUNT);
  TEST_ASSERT_EQUAL_INT(0, zone_index("UOL"));
  TEST_ASSERT_EQUAL_INT(15, zone_index("LCL"));
  TEST_ASSERT_EQUAL_INT(-1, zone_index("XXX"));
  char b[32];
  zone_name("UOL", b, sizeof b);
  TEST_ASSERT_EQUAL_STRING("upper left outside", b);
  TEST_ASSERT_TRUE(fabs(GYRO_RAD_S - 4.5 * 3.14159265358979323846 / 180.0) < 1e-12);
}

// Replays raw samples through the tracker, checking every window's feature and zone.
template <typename Fn>
static void replay(const std::vector<Golden::S>& samples, const std::vector<Feat>& expect, Fn check_feature) {
  // Reproduce the tracker's windowing to get per-window raw chunks for the feature check.
  std::vector<ImuRaw> chunk;
  double start = 0;
  bool started = false;
  ZoneTracker tr;
  size_t w = 0;
  uint32_t prev = 0;
  for (auto& s : samples) {
    if (!started) { start = s.t; started = true; }
    bool flush = s.t - start >= WINDOW && !chunk.empty();
    if (flush) {
      double x[FEATURE_COUNT];
      if (imu12_feature(chunk.data(), chunk.size(), x)) {
        TEST_ASSERT_TRUE_MESSAGE(w < expect.size(), "more windows than Python");
        check_feature(x, expect[w]);
        w++;
      }
      chunk.clear();
      start = s.t;
    }
    ImuRaw r;
    for (int i = 0; i < 3; i++) { r.a[i] = (int8_t)s.a[i]; r.g[i] = (int8_t)s.g[i]; }
    chunk.push_back(r);
    tr.add(s.t, s.a[0], s.a[1], s.a[2], s.g[0], s.g[1], s.g[2]);
    if (tr.windows != prev) {
      prev = tr.windows;
      TEST_ASSERT_EQUAL_INT_MESSAGE(expect[prev - 1].zone, tr.current, "tracker zone differs from Python");
    }
  }
  TEST_ASSERT_EQUAL_UINT(expect.size(), w);
}

static void check_close(const double* x, const Feat& e) {
  for (int i = 0; i < FEATURE_COUNT; i++) {
    char msg[64];
    snprintf(msg, sizeof msg, "feature %d: %.17g vs %.17g", i, x[i], e.x[i]);
    TEST_ASSERT_TRUE_MESSAGE(fabs(x[i] - e.x[i]) < 1e-9, msg);
  }
}

static void test_features_and_tracker_match_python() {
  Golden& g = golden();
  TEST_ASSERT_EQUAL_INT(1500, (int)g.samples.size());
  TEST_ASSERT_TRUE(g.replay.size() > 40);
  replay(g.samples, g.replay, check_close);
}

static void test_missing_gyro_counts_as_zeros() {
  Golden& g = golden();
  TEST_ASSERT_EQUAL_INT(300, (int)g.nogyro.size());
  TEST_ASSERT_TRUE(g.replay_nogyro.size() > 5);
  replay(g.nogyro, g.replay_nogyro, check_close);
}

static void test_filter_sequence_matches_python() {
  Golden& g = golden();
  TEST_ASSERT_TRUE(g.full.size() > 200);
  ZoneFilter flt;
  int mismatches = 0, first = -1;
  for (size_t i = 0; i < g.full.size(); i++) {
    int z = flt.update(g.full[i].x);
    if (z != g.full[i].zone) {
      mismatches++;
      if (first < 0) first = (int)i;
    }
  }
  char msg[96];
  snprintf(msg, sizeof msg, "%d zone mismatches, first at window %d", mismatches, first);
  TEST_ASSERT_EQUAL_INT_MESSAGE(0, mismatches, msg);
}

static void test_tracker_coverage_matches_python() {
  Golden& g = golden();
  ZoneTracker tr;
  for (auto& s : g.samples) tr.add(s.t, s.a[0], s.a[1], s.a[2], s.g[0], s.g[1], s.g[2]);
  TEST_ASSERT_EQUAL_UINT32(g.trk_windows, tr.windows);
  TEST_ASSERT_EQUAL_INT(g.trk_current, tr.current);
  for (int z = 0; z < ZONE_COUNT; z++) TEST_ASSERT_TRUE(fabs(g.cov[z] - tr.coverage[z]) < 1e-9);
  tr.reset();
  TEST_ASSERT_EQUAL_INT(-1, tr.current);
  TEST_ASSERT_EQUAL_UINT32(0, tr.samples);
  TEST_ASSERT_TRUE(tr.coverage[0] == 0.0);
}

void run_zone_tests() {
  RUN_TEST(test_embedded_model_metadata);
  RUN_TEST(test_features_and_tracker_match_python);
  RUN_TEST(test_missing_gyro_counts_as_zeros);
  RUN_TEST(test_filter_sequence_matches_python);
  RUN_TEST(test_tracker_coverage_matches_python);
}
